// Generated by create-video. All film metadata comes from the local registry.
import{readFile,mkdir,cp,writeFile}from'node:fs/promises';
const root=new URL('../',import.meta.url);const reg=JSON.parse(await readFile(new URL('source/films/registry.json',root),'utf8'));
for(const film of reg.films){if(!/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(film.slug))throw Error('Unsafe film slug');await mkdir(new URL('dist/science/',root),{recursive:true});await cp(new URL(`source/films/${film.slug}/media/`,root),new URL(`dist/science/${film.slug}-media/`,root),{recursive:true});await cp(new URL(`source/films/${film.slug}/index.html`,root),new URL(`dist/science/${film.slug}.html`,root));}
const file=new URL('dist/science.html',root);let html=await readFile(file,'utf8');
for(const film of reg.films){const marker=`data-film="${film.slug}"`;if(html.includes(marker))continue;const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const card=`<a ${marker} href="science/${film.slug}.html"><strong>${escape(film.title)}</strong><span>完整中文科普视频 →</span></a>`;if(!html.includes('<div class="light-links">'))throw Error('Science directory insertion point missing; adapt it explicitly');html=html.replace('<div class="light-links">','<div class="light-links">'+card);}
await writeFile(file,html);console.log(`Built ${reg.films.length} registered films`);
